-- Mathematics canonical assessment projection
-- Source canonical dataset: Mathematics grades 6-9
-- Canonical requirements: 290
-- Canonical nodes: 165
-- Legacy assessment topics preserved: M6-SH, M6-HH, M6-TKXS
--
-- Contract:
--   assert-or-insert
--   no blind update
--   semantic conflict = migration failure
--   repeated execution = idempotent

DO $$
DECLARE
    existing_record record;
BEGIN
    SELECT
        program_code,
        subject_code,
        education_level,
        grade_min,
        grade_max,
        version_label,
        status
    INTO existing_record
    FROM public.assessment_curriculum_programs
    WHERE program_code = 'MOET-GDPT2018-MATH-THCS';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'MATH_ASSESSMENT_PROGRAM_MISSING';
    END IF;

    IF existing_record.subject_code <> 'MATH'
       OR existing_record.education_level <> 'THCS'
       OR existing_record.grade_min <> 6
       OR existing_record.grade_max <> 9
       OR existing_record.version_label <> 'GDPT-2018-CURRENT'
       OR existing_record.status <> 'ACTIVE'
    THEN
        RAISE EXCEPTION 'MATH_ASSESSMENT_PROGRAM_CONFLICT';
    END IF;
END
$$;

DO $$
DECLARE
    existing_record record;
BEGIN
    SELECT
        topic_code,
        program_code,
        parent_topic_code,
        grade_level,
        domain_code,
        sequence_number,
        status
    INTO existing_record
    FROM public.assessment_curriculum_topics
    WHERE topic_code = 'M6-SH';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'LEGACY_MATH_TOPIC_MISSING: M6-SH';
    END IF;

    IF existing_record.program_code <> 'MOET-GDPT2018-MATH-THCS'
       OR existing_record.parent_topic_code IS NOT NULL
       OR existing_record.grade_level <> 6
       OR existing_record.domain_code <> 'NUMBER_AND_ALGEBRA'
       OR existing_record.sequence_number <> 10
       OR existing_record.status <> 'ACTIVE'
    THEN
        RAISE EXCEPTION 'LEGACY_MATH_TOPIC_CONFLICT: M6-SH';
    END IF;
END
$$;

