DO $$
DECLARE
    existing_record record;
BEGIN
    SELECT
        topic_code,
        program_code,
        parent_topic_code,
        grade_level,
        domain_code,
        topic_name,
        sequence_number,
        status
    INTO existing_record
    FROM public.assessment_curriculum_topics
    WHERE topic_code = 'CURR-NODE-MATH-G6-001';

    IF FOUND THEN
        IF existing_record.program_code IS DISTINCT FROM 'MOET-GDPT2018-MATH-THCS'
           OR existing_record.parent_topic_code IS DISTINCT FROM NULL
           OR existing_record.grade_level IS DISTINCT FROM 6
           OR existing_record.domain_code IS DISTINCT FROM 'CONTENT_STRAND'
           OR existing_record.topic_name IS DISTINCT FROM 'Số và Đại số'
           OR existing_record.sequence_number IS DISTINCT FROM 1
           OR existing_record.status IS DISTINCT FROM 'ACTIVE'
        THEN
            RAISE EXCEPTION 'MATH_TOPIC_CONFLICT: CURR-NODE-MATH-G6-001';
        END IF;
    ELSE
        INSERT INTO public.assessment_curriculum_topics (
            topic_code,
            program_code,
            parent_topic_code,
            grade_level,
            domain_code,
            topic_name,
            sequence_number,
            status,
            metadata
        ) VALUES (
            'CURR-NODE-MATH-G6-001',
            'MOET-GDPT2018-MATH-THCS',
            NULL,
            6,
            'CONTENT_STRAND',
            'Số và Đại số',
            1,
            'ACTIVE',
            '{"canonical":true,"canonical_subject_id":"subject-mathematics","canonical_node_type":"CONTENT_STRAND","canonical_code":"G6-NUM-ALG","canonical_status":"ACTIVE"}'::jsonb
        )
        ON CONFLICT (topic_code) DO NOTHING;
    END IF;
END
$$;

