DO $$
DECLARE
    canonical_topic_count integer;
    total_math_topic_count integer;
    canonical_requirement_count integer;
    active_requirement_count integer;
    verified_requirement_count integer;
    legacy_topic_count integer;
    orphan_parent_count integer;
    orphan_requirement_count integer;
    grade_6_count integer;
    grade_7_count integer;
    grade_8_count integer;
    grade_9_count integer;
BEGIN
    SELECT count(*) INTO canonical_topic_count
    FROM public.assessment_curriculum_topics
    WHERE program_code = 'MOET-GDPT2018-MATH-THCS'
      AND topic_code LIKE 'CURR-NODE-MATH-%';

    SELECT count(*) INTO total_math_topic_count
    FROM public.assessment_curriculum_topics
    WHERE program_code = 'MOET-GDPT2018-MATH-THCS';

    SELECT count(*) INTO canonical_requirement_count
    FROM public.assessment_learning_requirements
    WHERE program_code = 'MOET-GDPT2018-MATH-THCS'
      AND requirement_code LIKE 'YCCD-MATH-%';

    SELECT count(*) INTO active_requirement_count
    FROM public.assessment_learning_requirements
    WHERE program_code = 'MOET-GDPT2018-MATH-THCS'
      AND requirement_code LIKE 'YCCD-MATH-%'
      AND status = 'ACTIVE';

    SELECT count(*) INTO verified_requirement_count
    FROM public.assessment_learning_requirements
    WHERE program_code = 'MOET-GDPT2018-MATH-THCS'
      AND requirement_code LIKE 'YCCD-MATH-%'
      AND metadata ->> 'canonical_status' = 'VERIFIED';

    SELECT count(*) INTO legacy_topic_count
    FROM public.assessment_curriculum_topics
    WHERE topic_code IN ('M6-SH','M6-HH','M6-TKXS')
      AND program_code = 'MOET-GDPT2018-MATH-THCS';

    SELECT count(*) INTO orphan_parent_count
    FROM public.assessment_curriculum_topics child
    WHERE child.program_code = 'MOET-GDPT2018-MATH-THCS'
      AND child.topic_code LIKE 'CURR-NODE-MATH-%'
      AND child.parent_topic_code IS NOT NULL
      AND NOT EXISTS (
          SELECT 1
          FROM public.assessment_curriculum_topics parent
          WHERE parent.topic_code = child.parent_topic_code
      );

    SELECT count(*) INTO orphan_requirement_count
    FROM public.assessment_learning_requirements req
    WHERE req.program_code = 'MOET-GDPT2018-MATH-THCS'
      AND req.requirement_code LIKE 'YCCD-MATH-%'
      AND NOT EXISTS (
          SELECT 1
          FROM public.assessment_curriculum_topics topic
          WHERE topic.topic_code = req.topic_code
      );

    SELECT count(*) INTO grade_6_count
    FROM public.assessment_learning_requirements
    WHERE requirement_code LIKE 'YCCD-MATH-%'
      AND grade_level = 6;

    SELECT count(*) INTO grade_7_count
    FROM public.assessment_learning_requirements
    WHERE requirement_code LIKE 'YCCD-MATH-%'
      AND grade_level = 7;

    SELECT count(*) INTO grade_8_count
    FROM public.assessment_learning_requirements
    WHERE requirement_code LIKE 'YCCD-MATH-%'
      AND grade_level = 8;

    SELECT count(*) INTO grade_9_count
    FROM public.assessment_learning_requirements
    WHERE requirement_code LIKE 'YCCD-MATH-%'
      AND grade_level = 9;

    IF canonical_topic_count <> 165 THEN
        RAISE EXCEPTION 'MATH_CANONICAL_TOPIC_COUNT_INVALID: %', canonical_topic_count;
    END IF;

    IF total_math_topic_count <> 168 THEN
        RAISE EXCEPTION 'MATH_TOTAL_TOPIC_COUNT_INVALID: %', total_math_topic_count;
    END IF;

    IF canonical_requirement_count <> 290 THEN
        RAISE EXCEPTION 'MATH_CANONICAL_REQUIREMENT_COUNT_INVALID: %', canonical_requirement_count;
    END IF;

    IF active_requirement_count <> 290 THEN
        RAISE EXCEPTION 'MATH_ACTIVE_REQUIREMENT_COUNT_INVALID: %', active_requirement_count;
    END IF;

    IF verified_requirement_count <> 290 THEN
        RAISE EXCEPTION 'MATH_VERIFIED_REQUIREMENT_COUNT_INVALID: %', verified_requirement_count;
    END IF;

    IF legacy_topic_count <> 3 THEN
        RAISE EXCEPTION 'MATH_LEGACY_TOPIC_COUNT_INVALID: %', legacy_topic_count;
    END IF;

    IF orphan_parent_count <> 0 THEN
        RAISE EXCEPTION 'MATH_ORPHAN_PARENT_COUNT_INVALID: %', orphan_parent_count;
    END IF;

    IF orphan_requirement_count <> 0 THEN
        RAISE EXCEPTION 'MATH_ORPHAN_REQUIREMENT_COUNT_INVALID: %', orphan_requirement_count;
    END IF;

    IF grade_6_count <> 80
       OR grade_7_count <> 68
       OR grade_8_count <> 68
       OR grade_9_count <> 74
    THEN
        RAISE EXCEPTION
            'MATH_GRADE_DISTRIBUTION_INVALID: %/%/%/%',
            grade_6_count,
            grade_7_count,
            grade_8_count,
            grade_9_count;
    END IF;
END
$$;
